/**
 * Catalog emission dialect for automations (trigger / outputs bags).
 */
import { bareFactoryEntry, safeCatalogKey, } from "../../catalog/render-helpers.js";
export function renderAutomationCatalogEntry(args) {
    const ref = args.ref;
    const triggerKeys = Object.keys(ref.trigger ?? {}).sort();
    const outputKeys = Object.keys(ref.outputs ?? {}).sort();
    const { keyName, baseIndent } = args;
    if ((ref.name === "" || ref.name === keyName) && triggerKeys.length === 0 && outputKeys.length === 0) {
        return bareFactoryEntry("automationRef", keyName, baseIndent);
    }
    const lines = [`${baseIndent}${safeCatalogKey(keyName)}: automationRef({`];
    const extraFactories = [];
    if (ref.name !== "" && ref.name !== keyName) {
        lines.push(`${baseIndent}  name: ${JSON.stringify(ref.name)},`);
    }
    if (triggerKeys.length > 0) {
        extraFactories.push("triggerParameterRef");
        lines.push(`${baseIndent}  trigger: {`);
        for (const key of triggerKeys) {
            const param = ref.trigger[key];
            lines.push(`${baseIndent}    ${safeCatalogKey(key)}: triggerParameterRef({ name: ${JSON.stringify(param.name)}, parent: ${JSON.stringify(param.parent ?? "")}${param.required === true ? ", required: true" : ""} }),`);
        }
        lines.push(`${baseIndent}  },`);
    }
    if (outputKeys.length > 0) {
        extraFactories.push("outputPropertyRef");
        lines.push(`${baseIndent}  outputs: {`);
        for (const key of outputKeys) {
            const prop = ref.outputs[key];
            lines.push(`${baseIndent}    ${safeCatalogKey(key)}: outputPropertyRef({ name: ${JSON.stringify(prop.name)}, parent: ${JSON.stringify(prop.parent ?? "")}${prop.valueType !== undefined ? `, valueType: ${JSON.stringify(prop.valueType)}` : ""} }),`);
        }
        lines.push(`${baseIndent}  },`);
    }
    lines.push(`${baseIndent}}),`);
    return { lines, extraFactories };
}
